CREATE TABLE IF NOT EXISTS `oferta_plan_estudios` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `oferta_id` bigint(20) unsigned NOT NULL,
  `titulo` varchar(150) NOT NULL,
  `contenido` text NOT NULL,
  `orden` smallint(5) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_plan_oferta_orden` (`oferta_id`,`orden`,`id`),
  CONSTRAINT `fk_plan_estudios_oferta` FOREIGN KEY (`oferta_id`) REFERENCES `ofertas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `institucional_secciones` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `clave` varchar(40) NOT NULL,
  `version_actual` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `clave` (`clave`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `institucional_versiones` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `seccion_id` int(10) unsigned NOT NULL,
  `anio` smallint(5) unsigned NOT NULL,
  `usuario_id` int(11) DEFAULT NULL,
  `motivo` varchar(250) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_version_seccion` (`seccion_id`,`id`),
  CONSTRAINT `fk_institucional_seccion` FOREIGN KEY (`seccion_id`) REFERENCES `institucional_secciones` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `institucional_valores` (
  `version_id` int(10) unsigned NOT NULL,
  `campo` varchar(60) NOT NULL,
  `valor` text NOT NULL,
  PRIMARY KEY (`version_id`,`campo`),
  CONSTRAINT `fk_institucional_version` FOREIGN KEY (`version_id`) REFERENCES `institucional_versiones` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `institucional_autoridades` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(120) NOT NULL,
  `apellido` varchar(120) NOT NULL,
  `cargo` varchar(160) NOT NULL,
  `profesion` varchar(160) NOT NULL DEFAULT '',
  `descripcion` text NOT NULL,
  `imagen_url` varchar(500) NOT NULL DEFAULT '',
  `youtube_codigo` varchar(11) NOT NULL DEFAULT '',
  `video_url` varchar(500) NOT NULL DEFAULT '',
  `anio` smallint(5) unsigned NOT NULL,
  `visible` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `orden` smallint(5) unsigned NOT NULL DEFAULT 0,
  `revision` int(10) unsigned NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_autoridades_portada` (`visible`,`orden`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `institucional_autoridades_historial` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `autoridad_id` int(10) unsigned NOT NULL,
  `revision` int(10) unsigned NOT NULL,
  `usuario_id` int(11) DEFAULT NULL,
  `motivo` varchar(250) NOT NULL,
  `datos_json` longtext NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_autoridad_revision` (`autoridad_id`,`revision`),
  CONSTRAINT `fk_autoridad_historial` FOREIGN KEY (`autoridad_id`) REFERENCES `institucional_autoridades` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
